"""Schema validation for Claude Opus 5.5 Slow Brain state using Pydantic."""

from __future__ import annotations

import time
from typing import Literal
from pydantic import BaseModel, Field, field_validator


class SlowBrainState(BaseModel):
    """Schema-validated macro and regime state generated by Claude Opus 5.5."""

    z_VIX: float = Field(
        default=0.0,
        ge=-5.0,
        le=5.0,
        description="Standardized VIX / implied volatility z-score",
    )
    TrendAlign: int = Field(
        default=0,
        ge=-1,
        le=1,
        description="Macro trend alignment: -1 (bearish), 0 (neutral), 1 (bullish)",
    )
    VolExpansion: int = Field(
        default=0,
        ge=0,
        le=1,
        description="1 if volatility expansion cycle detected, 0 otherwise",
    )
    EventRisk: int = Field(
        default=0,
        ge=0,
        le=1,
        description="1 if high-impact macro or exchange event risk is imminent, 0 otherwise",
    )
    UniverseScore: float = Field(
        default=0.5,
        ge=0.0,
        le=1.0,
        description="Cross-asset liquidity and regime health score in [0, 1]",
    )
    risk_multiplier: float = Field(
        default=1.0,
        ge=0.0,
        le=1.0,
        description="Recommended risk multiplier m in [0, 1]. Can only tighten risk.",
    )
    confidence: float = Field(
        default=1.0,
        ge=0.0,
        le=1.0,
        description="Confidence score c in [0, 1]",
    )
    timestamp_ns: int = Field(
        default_factory=lambda: time.time_ns(),
        description="Timestamp of state generation in nanoseconds",
    )
    model_version: str = Field(
        default="claude-opus-5-5",
        description="Target model identifier",
    )

    @field_validator("risk_multiplier", mode="before")
    @classmethod
    def validate_risk_multiplier(cls, v: float) -> float:
        # Guarantee LLM cannot exceed 1.0 (cannot loosen risk)
        return min(1.0, max(0.0, float(v)))

    @classmethod
    def neutral_prior(cls, timestamp_ns: int = 0) -> SlowBrainState:
        """Returns the uninformative neutral prior state."""
        return cls(
            z_VIX=0.0,
            TrendAlign=0,
            VolExpansion=0,
            EventRisk=0,
            UniverseScore=0.5,
            risk_multiplier=1.0,
            confidence=0.0,
            timestamp_ns=timestamp_ns or time.time_ns(),
            model_version="neutral-prior",
        )
